)

func handler(ctx context.Context, req *http.Request) (interface{}, error) {
	// Create an EC2 session
	sess, err := session.NewSession(&aws.Config{Region: aws.String("your-region")}, nil)
	if err != nil {
		log.Println("error creating EC2 session:", err)
		return nil, err
	}
	ec2Svc := ec2.New(sess)

	// Define the retention policies
	retentionPolicies := map[string]int{
		"monthly": 14,
		"daily":   10,
		"weekly":  4,
		"yearly":  1,
	}

	// Get all EBS snapshots
	param := &ec2.DescribeSnapshotsInput{}
	snapshots, err := ec2Svc.DescribeSnapshots(param)
	if err != nil {
		log.Println("error describing snapshots:", err)
		return nil, err
	}

	// Iterate over the snapshots
	for _, snapshot := range snapshots.Snapshots {
		// Get the tag value
		tagValue, ok := getTagValue(snapshot, "backup_type")
		if !ok {
			log.Println("snapshot missing 'backup_type' tag:", *snapshot.SnAPSHOTId)
			continue
		}

		// Get the retention policy for this tag value
		retentionPolicy, ok := retentionPolicies[tagValue]
		if !ok {
			log.Println("unknown 'backup_type':", *snapshot.SnAPSHOTId)
			continue
		}

		// Get the snapshots for this backup type
	BackupTypeSnapshots := make([]*ec2.Snapshot, 0)
		for _, snap := range snapshots.Snapshots {
			if getTagValue(snap, "backup_type") == tagValue {
				BackupTypeSnapshots = append(BackupTypeSnapshots, snap)
			}
		}

		// Sort the snapshots by creation time
		sort.Slice(BackupTypeSnapshots, func(i, j int) bool {
			return *BackupTypeSnapshots[i].LaunchTime.Before(*BackupTypeSnapshots[j].LaunchTime)
		})

		// Delete the snapshots oldest than the retention policy
		for i := 0; i < len(BackupTypeSnapshots); i++ {
			if i >= len(BackupTypeSnapshots)-retentionPolicy {
				break
			}
			_, err := ec2Svc.DeleteSnapshot(&ec2.DeleteSnapshotInput{
				SnapshotId: &BackupTypeSnapshots[i].SnapshotId,
			})
			if err != nil {
				log.Println("error deleting snapshot:", *BackupTypeSnapshots[i].SnapshotId)
			}
		}
	}

	return nil, nil
}

func getTagValue(snapshot *ec2.Snapshot, tagName string) (string, bool) {
	for _, tag := range snapshot.Tags {
		if *tag.Key == tagName {
			return *tag.Value, true
		}
	}
	return "", false
}

